      "ref": "[D533]",
      "area": "contact",
      "claim": "A parent can turn off multiplayer and voice chat on a child account, and the default is off.",
      "stance": "mitigation",
      "quote": "On a child account, multiplayer starts off, and you choose whether others can communicate with your child: everyone, friends only, or no one."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "The Bedrock Edition Marketplace sells items for real money and requires purchase approvals.",
      "stance": "risk",
      "quote": "Bedrock Edition’s Marketplace sells maps, skins and mini-games for Minecoins, which are bought with real money, and Realms is a paid subscription. Set purchase approvals in your family settings."
    },
    {
      "ref": "[D533]",
      "area": "data",
      "claim": "Minecraft collects data through the Microsoft account and shares it with third parties for ads.",
      "stance": "risk",
      "quote": "Java Edition uses the same Microsoft account settings for multiplayer and communication, and adds a Player Reporting tool for abusive chat."
    },
    {
      "ref": "[D533]",
      "area": "age_gating",
      "claim": "The age gate requires a Microsoft account and is enforced through the account verification process.",
      "stance": "neutral",
      "quote": "Microsoft account age assurance is used to enforce age restrictions."
    },
    {
      "ref": "[D533]",
      "area": "content",
      "claim": "Minecraft contains no blood or realistic violence, making it suitable for young children.",
      "stance": "neutral",
      "quote": "Single-player Minecraft is generally gentle: no blood, blocky combat, and a Creative mode built around building rather than survival."
    }
  ]
